function renameMaintenanceLabels() {
	var newLabel = gs.getMessage('Active maintenance');
	var tablesToChange = ['samp_license_position_report',
		'samp_license_metric_result',
		'samp_remediation_option',
		'samp_software_change_projection',
		'alm_license'];
	// update field label of maintenance field
	for (var tableIndex = 0; tableIndex < tablesToChange.length; tableIndex += 1) {
		var currentTableName = tablesToChange[tableIndex];
		new GlideQuery('sys_dictionary')
			.where('name', currentTableName)
			.where('element', 'maintenance')
			.where('column_label', '!=', newLabel)
			.updateMultiple({ column_label: newLabel });
	}
}

renameMaintenanceLabels();
